// Extract file_id from Claude's response
const response = $input.first().json;

// Find the file_id in the content array
let fileId = null;
if (response.content && Array.isArray(response.content)) {
  for (const item of response.content) {
    if (item.type === 'code_execution' && item.content) {
      for (const subItem of item.content) {
        if (subItem.type === 'file' && subItem.file_id) {
          fileId = subItem.file_id;
          break;
        }
      }
    }
  }
}

return [{ json: { file_id: fileId, original_response: response } }];

